require(['jquery'], function($) {
  // Display the result of the job once it is finished: the job status only updates its log.
  var pending = $('#sopImportPending');
  var jobStatus = $('.job-status');
  if (pending.length && jobStatus.length) {
    var reloadWhenFinished = function() {
      if (!jobStatus.find('.ui-progress').length) {
        observer.disconnect();
        window.location.reload();
      }
    };
    var observer = new MutationObserver(reloadWhenFinished);
    observer.observe(jobStatus[0], {childList: true, subtree: true});
    reloadWhenFinished();
  }

  // One version per document: selecting a version unselects the other versions of the same document.
  var selection = $('#sopImportSelection');
  var updateCount = function() {
    var count = selection.find('input[name="file"]:checked').length;
    var counter = $('#sopImportSelectedCount');
    counter.text(counter.attr('data-label').replace('__count__', count));
    $('#sopImportSubmit').prop('disabled', count === 0);
  };
  selection.on('change', 'input[name="file"]', function() {
    if (this.checked) {
      $(this).closest('tr').find('input[name="file"]').not(this).prop('checked', false);
    }
    updateCount();
  });
  if (selection.length) {
    updateCount();
  }
  // The documents whose page exists are collapsed: expand them to see their details.
  selection.on('click', '.sopImportToggle', function() {
    var expanded = $(this).attr('aria-expanded') !== 'true';
    $(this).attr('aria-expanded', expanded);
    $('#' + $(this).attr('aria-controls')).toggleClass('hidden', !expanded);
  });

  // From the preview of a version, preview another version with the users selected in the preview.
  $(document).on('click', '#sopImportPreviewActions .sopImportPreviewSwitch', function() {
    var users = {};
    $('#sopImportPreviewActions .sopImportRole').each(function() {
      users['sopImportUser:' + $(this).attr('data-role')] = $(this).find('input.sopImportUser').val();
    });
    this.href += '&' + $.param(users);
  });

  // Preview a version directly in the preview mode of the editor: the window is opened on click (not blocked as a
  // popup), the content of the version is converted on the server, then sent to the preview action in this window.
  $(document).on('click', '#sopImportAnalysisTable .sopImportPreviewLink', function(event) {
    event.preventDefault();
    var link = $(this);
    var windowName = 'sopImportPreview' + new Date().getTime();
    var previewWindow = window.open('', windowName);
    if (!previewWindow) {
      // The window could not be opened: preview in this window.
      window.location = link.attr('href');
      return;
    }
    $.get(link.attr('href'), {'xpage': 'plain'}).done(function(html) {
      // Without running the script of the page, which submits the form.
      var form = $('<div></div>').append($.parseHTML(html)).find('#sopImportPreviewForm');
      if (form.length) {
        // The users selected in the analysis, to import the version with them from the preview.
        link.closest('tr').find('.sopImportRole').each(function() {
          var role = $(this).attr('data-role');
          form.find('input[name="sopImportUser:' + role + '"]').val($(this).find('input.sopImportUser').val());
        });
        form.attr('target', windowName).addClass('hidden').appendTo(document.body);
        form[0].submit();
        form.remove();
      } else {
        previewWindow.location = link.attr('href');
      }
    }).fail(function() {
      previewWindow.location = link.attr('href');
    });
  });
});

#sopImportForm input[type="text"] {
  max-width: 40em;
}
#sopImportForm input[type="number"] {
  max-width: 10em;
}
#sopImportReport .sopImportDetails ul, .sopImportWarnings {
  margin-bottom: 0;
  padding-left: 1.2em;
}
#sopImportReport .sopImportDetails p, #sopImportAnalysisTable p {
  margin: 0 0 .3em;
}
#sopImportAnalysisTable td {
  vertical-align: top;
}
#sopImportAnalysisTable .sopImportMissing {
  color: #999;
  text-align: center;
  vertical-align: middle;
}
#sopImportAnalysisTable .label, #sopImportAnalysisTable .btn {
  display: inline-block;
  max-width: 100%;
  white-space: normal;
}
#sopImportAnalysisTable .sopImportVersionFile {
  font-weight: normal;
  word-break: break-all;
}
#sopImportAnalysisTable .sopImportRecommendedVersion {
  background-color: rgba(92, 184, 92, .08);
}
#sopImportAnalysisTable details summary {
  cursor: pointer;
  font-size: .9em;
  color: #777;
}
/* Fixed layout, so that long values wrap instead of widening the cell. */
.sopImportProperties {
  table-layout: fixed;
  width: 100%;
  margin: .3em 0;
  font-size: .9em;
}
.sopImportProperties th, .sopImportProperties td {
  padding: 0 .8em 0 0;
  vertical-align: top;
  border: 0;
}
.sopImportProperties th {
  width: 40%;
  font-weight: normal;
  color: #777;
}
/* The table fits the width of the page content: the columns don't grow with their content. */
#sopImportAnalysisTable {
  table-layout: fixed;
  width: 100%;
  max-width: 100%;
  font-size: .9em;
}
#sopImportAnalysisTable .sopImportDocumentColumn {
  width: 40%;
}
#sopImportAnalysisTable td, #sopImportAnalysisTable th {
  overflow-wrap: anywhere;
}
.sopImportRole {
  margin-top: .3em;
}
.sopImportRoleName {
  display: block;
  margin: 0;
}
/* The user pickers, as small as the rest of the text (selectize up to XWiki 17, Tom Select from XWiki 18). */
.sopImportRole .selectize-control, .sopImportRole .ts-wrapper {
  max-width: 100%;
  margin-top: .2em;
  font-size: inherit;
}
.sopImportRole .selectize-input, .sopImportRole .ts-control {
  min-height: 0;
  padding: 2px 6px;
  font-size: inherit;
  line-height: 1.5;
}
/* Less room kept for the loading spinner (and the arrow of the single picker). */
.sopImportRole .selectize-control.multi .selectize-input, .sopImportRole .ts-wrapper.multi .ts-control {
  padding-right: 22px;
}
.sopImportRole .selectize-control.single .selectize-input, .sopImportRole .ts-wrapper.single .ts-control {
  padding-right: 42px;
}
/* Long user names wrap instead of widening the picker. */
.sopImportRole .xwiki-selectize-option {
  max-width: 100%;
  white-space: normal;
}
.sopImportRole .selectize-dropdown .xwiki-selectize-option, .sopImportRole .ts-dropdown .xwiki-selectize-option {
  white-space: nowrap;
}
.sopImportRole .selectize-input > input, .sopImportRole .ts-control > input {
  height: auto;
  min-width: 0;
  font-size: inherit;
}
.sopImportRole .selectize-dropdown, .sopImportRole .ts-dropdown {
  font-size: inherit;
}
.sopImportExists {
  font-size: .9em;
}
#sopImportAnalysisTable .sopImportExistingCandidate td {
  background-color: #f5f5f5;
}
#sopImportAnalysisTable .sopImportToggle {
  padding: 0 .5em 0 0;
  color: inherit;
}
#sopImportAnalysisTable .sopImportToggle::before {
  content: '\25B8';
  display: inline-block;
  width: 1em;
}
#sopImportAnalysisTable .sopImportToggle[aria-expanded="true"]::before {
  content: '\25BE';
}
#sopImportPreviewActions h3 {
  margin-top: 0;
  font-size: 1.1em;
}
#sopImportPreviewActions .panel-heading p {
  margin: 0;
}
#sopImportPreviewActions .sopImportPreviewVersion {
  margin-bottom: .5em;
  padding: .3em .5em;
  border-left: 3px solid #ddd;
}
#sopImportPreviewActions .sopImportPreviewVersion p {
  margin: 0 0 .2em;
}
#sopImportPreviewActions .sopImportRecommendedVersion {
  border-left-color: #5cb85c;
  background-color: rgba(92, 184, 92, .08);
}
#sopImportPreviewActions .sopImportUsers, #sopImportPreviewActions .sopImportPreviewData {
  overflow-wrap: anywhere;
}
